import {migrate,buildRound,questionFor,recordAttempt,grantXp,evolutionFor,completeRound,wrongList,wordOverview,progress,PARTNERS,NAMES,STAGES,STAGE_NAMES,applyLetter,wordStats,cleanText,checkInput} from './trainer-engine.mjs';
import {AudioQueue} from './voice.mjs';
import {GameSound} from './sound.mjs';
import {restoreProgress} from './progress-file.mjs';
const data=await fetch('data/words.json').then(r=>{if(!r.ok)throw Error('题库未加载');return r.json()});
const KEY='pokemon-english-trainer-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY))||{}}catch{}
let state=migrate(saved,data);if(!data.books.some(b=>b.id===state.book))state.book='upper';
const app=document.querySelector('#app'),sound=new GameSound();let screen='home',duo=false,session=null,status='',sheet=null,teamPlayer=0,reviewPlayer=0,resetConfirm=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pic=id=>`<img draggable="false" src="assets/pokemon-${id}.png" alt="${NAMES[id]||'伙伴'}">`;
const button=(action,text,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const modeNames={islands:'听写探险',energy:'字母能量站',egg:'单词孵蛋器',gym:'双人道馆赛',coop:'合作孵蛋',relay:'招式接力',mistakes:'错题练习'};
const book=()=>data.books.find(b=>b.id===state.book),word=()=>data.words.find(w=>w.id===session.tasks[session.index]?.item),task=()=>session.tasks[session.index],current=()=>session.current;
let slideDirection=0;let toastTimer;function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('保存失败，请到学习记录导出进度')}}
const voice=new AudioQueue((text,failed=false)=>{status=text;const el=document.querySelector('#audioStatus');if(el)el.textContent=text;if(failed&&screen==='play'){current().heard=false;sound.duck(false);save();unlockAnswers()}});
function stop(){voice.stop();sound.stop()}
function home(){stop();screen='home';session=null;sheet=null;render()}
function decorate(theme){return `<div class="environment ${theme}" aria-hidden="true"><i class="sun"></i><i class="cloud c1"></i><i class="cloud c2"></i><i class="mountain m1"></i><i class="mountain m2"></i><i class="terrain"></i><i class="tree t1"></i><i class="tree t2"></i><i class="crystal cr1"></i><i class="crystal cr2"></i><i class="floating f1"></i><i class="floating f2"></i><i class="floating f3"></i><i class="ripple r1"></i><i class="ripple r2"></i></div>`}
function header(){return `<header>${button('home','<i class="ball"></i><span>英语训练家</span>','brand')}<div class="header-actions">${screen==='play'?button('pause','Ⅱ 暂停','small-btn'):button('settings','⚙ 设置','small-btn')}${screen==='home'?'<a class="station-link small-btn" href="https://vivinzhang.github.io/pokemon-trainer/" aria-label="训练家小站主页"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/></svg><span>训练家小站</span></a>'+button('stats','学习记录','small-btn'):''}</div></header>`}
function homeUI(){const p=state.players[0],e=evolutionFor(p,p.partner),o=wordOverview(data,state,state.book),modes=duo?['gym','coop','relay']:['islands','energy','egg'],index=PARTNERS.findIndex(x=>x.id===p.partner),neighbors=[PARTNERS[(index+7)%8],PARTNERS[(index+1)%8]];return `<section class="home-scene">${decorate('meadow')}<div class="home-top"><div class="book-pills">${data.books.map(b=>button('book',b.title,state.book===b.id?'chosen':'',`data-id="${b.id}"`)).join('')}</div><div class="home-title"><span class="tiny">POKÉMON ENGLISH ADVENTURE</span><h1>伙伴，出发！</h1><p><b>${o.seen}/${o.words}</b> 个词已练习</p></div></div><div class="home-pokemon carousel ${slideDirection?'sliding-'+(slideDirection>0?'next':'prev'):''}" data-carousel aria-label="左右滑动选择伙伴"><div class="buddy-main">${pic(e.id)}<div class="buddy-label">${NAMES[e.id]} <span>左右滑动换伙伴</span></div></div>${neighbors.map((b,n)=>`<div class="buddy-side ${n?'right':'left'}">${pic(evolutionFor(p,b.id).id)}</div>`).join('')}${button('prevBuddy','‹','carousel-arrow prev','aria-label="上一个伙伴"')}${button('nextBuddy','›','carousel-arrow next','aria-label="下一个伙伴"')}<div class="carousel-dots">${PARTNERS.map(b=>`<i class="${b.id===p.partner?'active':''}"></i>`).join('')}</div><div class="home-egg"></div><i class="ball decor-ball"></i></div><div class="home-bottom"><div class="mode-tabs">${button('solo','一个人',!duo?'active':'')}${button('duo','两个人',duo?'active':'')}</div><div class="mode-cards">${modes.map((m,n)=>button('start',`<div class="mode-art ${m}">${m==='egg'||m==='coop'?'<div class="egg-art"></div>':'<div class="abc-art"><b>A</b><b>B</b><b>C</b></div>'}</div><div><h2>${modeNames[m]}</h2><p>${(duo?['左右答，一起揭晓','你听写，我补字母','轮流拼，组合出招']:['听英语，写单词','补字母，放招式','学单词，孵伙伴'])[n]}</p></div><span class="go">➜</span>`,'mode-card',`data-mode="${m}"`)).join('')}</div><div class="home-links">${button('wrong',`错题本 <b>${wrongList(state,state.book).length}</b>`,'soft-btn')}${state.sessions[state.book]&&!state.sessions[state.book].completed?button('resume','继续冒险','soft-btn'):''}${button('team','伙伴图鉴','soft-btn')}</div></div></section>`}
function owner(player=null){if(player!=null)return player;const t=task();return session.mode==='relay'?(t.owner+current().parts[0].typed.length)%2:t.owner??0}
function part(player=0){return current().parts[session.mode==='gym'?player:0]}
function prepare(){const t=task();if(!t){finish();return}if(!current()||current().task!==t.id){const q=questionFor(data,word(),t.stage);session.current={task:t.id,q,heard:false,parts:[0,1].map(()=>({typed:'',used:[],hints:0,mistakes:0,answer:null,error:''})),feedback:null};save()}}
function enter(){screen='play';sheet=null;prepare();sound.unlock();sound.music=state.settings.music;sound.effects=state.settings.effects;sound.scene(session.mode);render();if(!current().feedback)play()}
function start(mode){sound.unlock();const previous=state.sessions[state.book];if(previous&&!previous.completed){session=previous;sheet={type:'pending',mode};render();return}createRound(mode)}
function createRound(mode){session=buildRound(data,state,state.book,{mode,player:mode==='mistakes'?reviewPlayer:null});if(!session.tasks.length){toast('错题已清空，继续新的冒险吧！');return}state.rounds[state.book]=session.round;state.sessions[state.book]=session;save();enter()}
function play(){if(screen!=='play'||!current())return;sound.duck(true);const id=session.id,index=session.index;voice.play(current().q.listen,{onHeard:()=>{sound.duck(false);if(screen!=='play'||session.id!==id||session.index!==index)return;current().heard=true;if(!current().feedback){for(const p of session.mode==='gym'?[0,1]:[owner()])recordAttempt(state,session,task(),{player:p,type:'heard',correct:null})}save();unlockAnswers()}})}
function activePlayer(player){return !sheet&&screen==='play'&&current().heard&&!current().feedback&&part(player).answer===null&&(session.mode==='gym'||session.scope==='solo'||player===owner())}
function unlockAnswers(){document.querySelectorAll('[data-key],[data-entry],[data-action="submit"],[data-action="hint"],[data-action="undo"],[data-action="skipPlayer"]').forEach(el=>{const player=Number(el.dataset.player)||0;el.disabled=!activePlayer(player)||(el.dataset.action==='undo'&&!part(player).typed)})}
function slotsUI(player){const q=current().q,p=part(player),clean=cleanText(q.word);let pos=0;return `<div class="word-slots ${clean.length>12?'long-word':''}">${q.word.split(' ').map(seg=>'<span class="word-part">'+[...seg].filter(c=>/[a-z]/i.test(c)).map(()=>{const n=pos++,v=q.level===1?(n===q.bank.missing?p.typed[0]||'':clean[n]):cleanText(p.typed)[n]||'';return `<span class="letter-slot ${v?'filled':''} ${q.level===1&&n===q.bank.missing?'missing':''}">${v||'·'}</span>`}).join('')+'</span>').join('<i class="word-gap"></i>')}</div>`}
function spellUI(player){
 const q=current().q,p=part(player),w=word(),enabled=activePlayer(player),hint=q.level<3||p.hints>0,two=session.scope!=='solo';
 const keyButton=k=>`<button class="input-key" data-key="${k}" data-player="${player}" ${enabled?'':'disabled'}>${k}</button>`;
 const prompt=`<div class="spell-prompt">${hint?(w.image?`<img src="${w.image}" alt="${esc(w.meaning)}">`:`<strong>${esc(w.meaning)}</strong>`):'<div class="listen-orb" aria-label="听音输入">♫</div>'}</div>`;
 const clue=two?`<div class="duo-clue">${prompt}${slotsUI(player)}</div>`:prompt+slotsUI(player);
 const keys=two?[...'abcdefghijklmnopqrstuvwxyz'].map(keyButton).join(''):['qwertyuiop','asdfghjkl','zxcvbnm'].map(row=>`<div class="key-row">${[...row].map(keyButton).join('')}</div>`).join('');
 return `${clue}<div class="entry-bar">${session.mode!=='relay'?`<input data-entry data-player="${player}" aria-label="${esc(state.players[player].name)}的英文输入" inputmode="text" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" maxlength="60" placeholder="${q.level===1?'输入缺少的字母':'输入单词，也可点下面字母'}" value="${esc(p.typed)}" ${enabled?'':'disabled'}>`:`<span class="relay-note">${esc(state.players[player].name)} · 输入第 ${p.typed.length+1} 个字母</span>`}</div><div class="touch-keyboard ${two?'duo-keyboard':''}" aria-label="英文触屏键盘">${keys}</div><div class="input-error" role="status">${esc(p.error||'')}</div><div class="spell-tools">${button('undo','⌫','soft-btn',`aria-label="删除一个字母" data-player="${player}" ${enabled&&p.typed?'':'disabled'}`)}${button('hint','提示','soft-btn',`data-player="${player}" ${enabled?'':'disabled'}`)}${session.mode!=='relay'?button('submit','确定 ✓','primary',`data-player="${player}" ${enabled?'':'disabled'}`):''}${two?button('skipPlayer','稍后再练','skip-btn',`data-player="${player}" ${current().heard?'':'disabled'}`):''}</div>`;
}
function waitingUI(player,submitted=false){const profile=state.players[player],e=evolutionFor(profile,profile.partner);return `<div class="waiting waiting-animated"><div class="waiting-orbit"><i></i><i></i><i></i>${pic(e.id)}</div><h3>${submitted?'已提交':'对方答题中……'}</h3><p>${submitted?'等伙伴一起揭晓':'伙伴正在积蓄能量'}</p><div class="energy-dots"><i></i><i></i><i></i></div></div>`}
function playerZone(player){const p=part(player),profile=state.players[player],e=evolutionFor(profile,profile.partner),active=session.mode==='gym'||player===owner();return `<section class="player-zone p${player} ${active?'is-active':'is-waiting'}" data-zone="${player}"><div class="zone-name">${pic(e.id)}<b>${esc(profile.name)}</b><span>${session.scores[player]} ⚡</span></div>${session.mode==='gym'&&p.answer!==null?waitingUI(player,true):!active?waitingUI(player):spellUI(player)}</section>`}
function stageTitle(){const q=current().q;return session.mode==='relay'?'轮流输入一个字母':q.level===1?'输入缺少的字母':q.level===2?'听一听，输入单词':'听英语，写单词'}
function gameUI(){const feedback=current().feedback,theme=['islands','gym'].includes(session.mode)?'islands':['egg','coop'].includes(session.mode)?'egg':'energy',player=owner(),e=evolutionFor(state.players[player],state.players[player].partner),two=session.scope!=='solo';return `<section class="game-scene theme-${theme} mode-${session.mode}">${decorate(theme)}<div class="game-top"><span class="mode-label">${modeNames[session.mode]}</span><div class="round-dots" aria-label="本轮进度">${session.tasks.map((t,n)=>`<i class="${n<session.index?'done':n===session.index?'now':''}"></i>`).join('')}</div><span class="counter">${session.index+1}/${session.tasks.length}</span></div>${feedback?feedbackUI():`<div class="question-heading"><h1>${stageTitle()}</h1><div class="audio-row">${button('replay','↻ 重听','audio-btn')}<span id="audioStatus" role="status">${esc(status||'听一听…')}</span></div></div><div class="task-area ${two?'duo-board':''}">${two?playerZone(0)+playerZone(1):spellUI(player)}</div>${two?'':`<div class="game-bottom"><div class="active-buddy">${pic(e.id)}<div><b>${NAMES[e.id]}</b><span>${session.scores[player]} ⚡</span></div></div>${session.mode==='egg'?`<div class="egg-progress"><div class="egg-art"></div><div><b>孵化能量</b><progress value="${session.eggEnergy}" max="${session.tasks.length}"></progress></div></div>`:'<div class="quest-device"><i></i><span>单词能量充能中</span></div>'}${button('skip','稍后再练','skip-btn')}</div>`}`}</section>`}
function wrongAnimation(player){const el=document.querySelector(`[data-zone="${player}"]`)||document.querySelector('.task-area');if(!el)return;el.querySelector('.error-effect')?.remove();const fx=document.createElement('div');fx.className='error-effect';fx.innerHTML='<div class="repair-shield"><i></i><b>再试一次</b><span>✦</span></div>';el.append(fx);el.classList.remove('answer-wobble');void el.offsetWidth;el.classList.add('answer-wobble');setTimeout(()=>{fx.remove();el.classList.remove('answer-wobble')},1000);sound.effect('wrong')}
function inputChanged(player){const p=part(player);document.querySelector(`[data-entry][data-player="${player}"]`)?.setAttribute('value',p.typed);const input=document.querySelector(`[data-entry][data-player="${player}"]`);if(input)input.value=p.typed;const zone=document.querySelector(`[data-zone="${player}"]`)||document.querySelector('.task-area'),slots=zone?.querySelector('.word-slots');if(slots){const t=document.createElement('template');t.innerHTML=slotsUI(player);slots.replaceWith(t.content.firstElementChild)}const err=zone?.querySelector('.input-error');if(err)err.textContent=p.error;const undo=zone?.querySelector('[data-action="undo"]');if(undo)undo.disabled=!p.typed;save()}
function typeKey(key,player){if(!activePlayer(player))return;const p=part(player),q=current().q;
 if(session.mode==='relay'){const expected=cleanText(q.word)[p.typed.length];if(key!==expected){p.mistakes++;p.error=`第 ${p.typed.length+1} 个字母再想想，已拼部分保留`;recordAttempt(state,session,task(),{correct:false,player,event:'letter'});inputChanged(player);wrongAnimation(player);return}p.typed+=key;p.used.push(player);p.error='';session.contributions[player]++;recordAttempt(state,session,task(),{correct:null,player,type:'practice',event:'letter'});if(p.typed===cleanText(q.word)){answer(player,true);return}save();render();return}
 p.typed=q.level===1?key:(p.typed+key).slice(0,60);p.error='';inputChanged(player);
}
function submit(player){if(!activePlayer(player))return;const p=part(player),q=current().q;if(!p.typed){toast('先输入字母吧');return}const good=q.level===1?cleanText(p.typed)===cleanText(q.word)[q.bank.missing]:checkInput(word(),p.typed);
 if(!good){p.mistakes++;recordAttempt(state,session,task(),{correct:false,player});p.error=q.level===1?'这个字母再想想':`再听一次，检查第 ${firstDifferent(cleanText(p.typed),cleanText(q.word))+1} 个字母`;
 // Preserve the input for editing; a wrong submission never resets the team.
 inputChanged(player);wrongAnimation(player);return}answer(player,true)}
function firstDifferent(a,b){for(let n=0;n<Math.max(a.length,b.length);n++)if(a[n]!==b[n])return n;return 0}
function slideBuddy(direction){const p=state.players[0],n=PARTNERS.findIndex(x=>x.id===p.partner);p.partner=PARTNERS[(n+direction+8)%8].id;slideDirection=direction;save();render();slideDirection=0}
function effectArt(type){return `<div class="move-effect ${type}"><svg viewBox="0 0 600 210" aria-hidden="true">${type==='electric'?'<path d="M25 150L180 70 150 135 300 25 270 105 530 50 390 140 430 90 210 180"/>':type==='grass'?'<path d="M15 170Q150 20 310 140T580 40"/><path d="M80 130Q200 170 350 60T570 150"/>':type==='fire'?'<path d="M90 180Q60 120 125 70Q150 130 185 20Q200 90 260 120Q280 50 320 25Q360 150 400 90Q450 140 470 180Z"/>':type==='water'?'<path d="M20 125Q150 40 250 130T560 80"/><path d="M20 155Q150 70 250 160T560 110"/>':type==='music'?'<text x="210" y="150" font-size="130">♫ ♪</text>':'<path d="M300 20L325 90 410 95 345 145 365 200 300 165 235 200 255 145 190 95 275 90Z"/>'}</svg>${Array.from({length:12},(_,n)=>`<i style="--n:${n}"></i>`).join('')}</div>`}
function feedbackUI(){const f=current().feedback,w=word(),e=evolutionFor(state.players[f.player??0],state.players[f.player??0].partner);return `<div class="feedback-stage ${f.success?'success':'try-again'}">${f.success?effectArt(e.type):'<div class="repair-shield feedback-repair"><i></i><b>能量修复中</b><span>✦</span></div>'}<div class="attack-partners ${session.scope!=='solo'?'pair':''}">${(session.scope!=='solo'?[0,1]:[f.player??0]).map(k=>{const pe=evolutionFor(state.players[k],state.players[k].partner);return `<div class="attacker ${session.mode==='gym'&&!current().parts[k].answer?'incorrect':''}">${session.mode==='gym'&&!current().parts[k].answer?'<i class="small-repair">↻</i>':''}${pic(pe.id)}<span>${session.scope!=='solo'?esc(state.players[k].name)+(session.mode==='gym'?(current().parts[k].answer?' · 充能成功':' · 下次再试'):''):pe.move}</span></div>`}).join('')}</div><h2>${f.success?(session.scope==='solo'?`${e.move}！`:session.mode==='gym'?'一起充能！':'组合招式！'):'记住它，下次再试'}</h2><div class="word-reveal"><strong>${esc(w.text)}</strong><span>${esc(w.meaning)}</span></div>${f.evolution?`<div class="evolution-banner">${pic(f.evolution.from)}<span>进化！➜</span>${pic(f.evolution.to)}<b>${NAMES[f.evolution.to]}</b></div>`:`<p>${f.success?'能量已点亮！': '慢慢来，你正在进步'}</p>`}${session.mode==='mistakes'?`<p class="retry-streak">错题连续答对 ${wrongList(state,state.book).find(x=>x.item===w.id&&x.stage===task().stage&&x.player===owner())?.streak??2}/2</p>`:''}<div class="feedback-actions">${button('replay','↻ 再听一次','soft-btn')}${button('next',session.index+1===session.tasks.length?'领取奖励 ➜':'下一题 ➜','primary')}</div></div>`}
function updateZone(player){const el=document.querySelector(`[data-zone="${player}"]`);if(!el){render();return}const template=document.createElement('template');template.innerHTML=playerZone(player);el.replaceWith(template.content.firstElementChild);bind()}
function answer(player,correct,assisted=false){const t=task(),p=part(player);if(p.answer!==null)return;const helped=assisted||p.hints>0||p.mistakes>0;p.answer=correct;const r=recordAttempt(state,session,t,{correct,assisted:helped,player});session.results.push(r);
 let evolution=null;if(correct){session.scores[player]+=helped?1:2;session.contributions[player]++;evolution=grantXp(state,player,session,t,helped);if(evolution)session.evolutions.push(evolution)}
 if(session.mode==='gym'){save();if(current().parts.some(p=>p.answer===null)){updateZone(player);return}const correctPlayers=current().parts.flatMap((p,k)=>p.answer?[k]:[]);show({success:correctPlayers.length>0,player:correctPlayers[0]||0,correctPlayers,evolution});return}
 if(correct){if(session.mode==='coop'){const completed=session.tasks.filter(x=>x.pair===t.pair).every(x=>session.results.some(r=>r.item===x.item&&r.stage===x.stage&&r.correct));if(completed)session.eggEnergy+=2}else session.eggEnergy++}
 show({success:correct,player,evolution});
}
function show(feedback){current().feedback=feedback;save();voice.stop();sound.duck(false);sound.effect(feedback.success?(feedback.evolution?'evolve':evolutionFor(state.players[feedback.player],state.players[feedback.player].partner).type):'wrong');render()}
function hint(player){if(!activePlayer(player))return;const p=part(player);p.hints++;p.error='';save();if(session.mode==='gym')updateZone(player);else render();const clean=cleanText(word().text);if(p.hints===1){toast('看看词义，再听一次');play()}else if(p.hints===2)toast(`首字母 ${clean[0]}，共 ${clean.length} 个字母`);else toast(`下一步：${clean[current().q.level===1?current().q.bank.missing:p.typed.length]||clean.at(-1)}`)}
function next(){voice.stop();session.index++;session.current=null;save();if(session.index>=session.tasks.length)finish();else{prepare();render();play()}}
function finish(){stop();completeRound(state,session);save();screen='result';render();sound.effect('egg')}
function resultUI(){const o=wordOverview(data,state,state.book),reward=session.reward;return `<section class="result-scene">${decorate('meadow')}<div class="result-content"><span class="tiny">ADVENTURE COMPLETE</span><h1>${session.scope==='solo'?'这轮冒险完成！':'两位训练家，做得好！'}</h1><div class="reward-partner">${pic(reward||evolutionFor(state.players[0],state.players[0].partner).id)}<div class="sparkle-ring"></div></div><h2>${reward?`伙伴 ${NAMES[reward]} 加入成长！`:'这次练习已保存'}</h2><div class="result-stats"><span><b>${session.results.filter(r=>r.correct&&!r.assisted).length}</b>独立完成</span><span><b>${session.results.filter(r=>r.correct&&r.assisted).length}</b>帮助后完成</span><span><b>${wrongList(state,state.book).length}</b>错题待练</span></div>${session.scope!=='solo'?`<p>${esc(state.players[0].name)} ${session.scores[0]} ⚡　${esc(state.players[1].name)} ${session.scores[1]} ⚡${session.mode==='gym'&&session.scores[0]===session.scores[1]&&session.scores[0]>0?' · 双训练家获胜！':''}</p>`:`<p>本册已练习 ${o.seen}/${o.words} · 休息一下，看看远处吧</p>`}<div class="feedback-actions">${button('home','回首页','primary')}${button('wrong','看看错题本','soft-btn')}</div></div></section>`}
function wrongUI(){const rows=wrongList(state,state.book,reviewPlayer);return `<section class="panel-page"><div class="page-title"><h1>我的错题本</h1><span>${book().title}</span></div><div class="mode-tabs">${state.players.map((p,k)=>button('reviewPlayer',esc(p.name),reviewPlayer===k?'active':'',`data-player="${k}"`)).join('')}</div><p class="muted">连续两次独立答对，就移出错题本</p><div class="list-scroll">${rows.length?rows.map(r=>{const w=data.words.find(w=>w.id===r.item);return `<div class="wrong-row">${w.image?`<img src="${w.image}" alt="${esc(w.meaning)}">`:'<i class="word-icon">Aa</i>'}<div><strong>${esc(w.text)}</strong><span>${esc(w.meaning)} · ${STAGE_NAMES[r.stage]}</span></div><b>${r.streak}/2</b></div>`}).join(''):'<div class="empty">'+pic('025')+'<h2>错题本空空的，继续探索吧！</h2></div>'}</div><div class="page-bottom">${button('home','回首页','soft-btn')}${rows.length?button('start','打乱顺序，再练一次 ➜','primary','data-mode="mistakes"'):''}</div></section>`}
function teamUI(){const p=state.players[teamPlayer],e=evolutionFor(p,p.partner);return `<section class="panel-page team-page"><div class="page-title"><h1>我的伙伴</h1><div class="mode-tabs">${state.players.map((p,k)=>button('teamPlayer',esc(p.name),teamPlayer===k?'active':'',`data-player="${k}"`)).join('')}</div></div><div class="team-grid">${PARTNERS.map(base=>{const pe=evolutionFor(p,base.id);return button('partner',`${pic(pe.id)}<strong>${NAMES[pe.id]}</strong><span>${pe.xp} 成长 · ${pe.next?`到 ${pe.next} 进化`:'继续成长'}</span>`,'partner-card '+(p.partner===base.id?'chosen':''),`data-id="${base.id}"`)}).join('')}</div><div class="evolution-path">${PARTNERS.find(b=>b.id===p.partner).chain.map((id,n)=>`${n?'<span>➜</span>':''}<div class="${n>e.stage?'future':''}">${pic(id)}<b>${NAMES[id]}</b></div>`).join('')}</div><div class="page-bottom"><label>昵称 <input data-name="${teamPlayer}" maxlength="12" value="${esc(p.name)}"></label>${button('home','带它出发 ➜','primary')}</div></section>`}
function statsUI(){const o=wordOverview(data,state,state.book),answers=state.records.filter(r=>r.book===state.book&&r.type==='answer');return `<section class="panel-page"><div class="page-title"><h1>学习记录</h1><span>${book().title}</span></div><div class="record-stats"><span><b>${o.seen}/${o.words}</b>已练单词</span><span><b>${o.mastered}</b>完成全部阶段</span><span><b>${o.wrong}</b>错题待练</span></div><p class="muted">次数按每位训练家的每道任务计算，重听不重复计数</p><div class="list-scroll"><table><thead><tr><th>单词</th><th>练习次数</th><th>独立答对</th><th>提示后答对</th><th>错误次数</th>${STAGES.map(s=>`<th>${STAGE_NAMES[s]}</th>`).join('')}</tr></thead><tbody>${data.words.filter(w=>w.book===state.book).map(w=>{const st=wordStats(state,w);return `<tr><td><b>${esc(w.text)}</b><small>${esc(w.meaning)}</small></td><td class="practice-count">${st.times}</td><td>${st.independent}</td><td>${st.helped}</td><td>${st.errors}</td>${STAGES.map(s=>`<td>${progress(state,w,s)?'✓':answers.some(r=>r.item===w.id&&r.stage===s&&r.correct&&r.assisted)?'提示后':'—'}</td>`).join('')}</tr>`}).join('')}</tbody></table></div><div class="page-bottom">${button('home','回首页','soft-btn')}${button('export','导出进度','soft-btn')}${button('import','导入进度','soft-btn')}</div></section>`}
function sheetUI(){if(!sheet)return '';let html='';if(sheet.type==='pending')html=`<h2>上次冒险还在这里</h2><p>已完成 ${session.index}/${session.tasks.length} 题</p><div class="sheet-actions">${button('resume','继续上次冒险','primary')}${button('newRound','保存并开始新冒险','soft-btn',`data-mode="${sheet.mode}"`)}</div>`;
 if(sheet.type==='pause')html=`<h2>休息一下</h2><div class="pause-buddy">${pic(evolutionFor(state.players[0],state.players[0].partner).id)}</div><div class="sheet-actions">${button('resume','继续冒险','primary')}${button('home','保存并回首页','soft-btn')}</div>`;
 if(sheet.type==='settings')html=`<h2>设置</h2><div class="setting-row"><span>背景音乐</span>${button('music',state.settings.music?'开启':'关闭',state.settings.music?'toggle on':'toggle')}</div><div class="setting-row"><span>招式音效</span>${button('effects',state.settings.effects?'开启':'关闭',state.settings.effects?'toggle on':'toggle')}</div><div class="setting-row"><span>减少动画</span>${button('reduced',state.settings.reduced?'开启':'关闭',state.settings.reduced?'toggle on':'toggle')}</div><p class="muted">纯触屏 · 英文读音已内置</p><div class="sheet-actions">${button('closeSheet','完成','primary')}${button('reset',resetConfirm?'确认清空当前设备进度':'重置进度','text-btn')}</div>`;
 return `<div class="modal-backdrop"><section class="sheet" role="dialog" aria-modal="true">${html}</section></div>`}
function render(){document.body.classList.toggle('reduce-motion',state.settings.reduced);app.innerHTML=`<main class="app-shell">${header()}${({home:homeUI,play:gameUI,wrong:wrongUI,team:teamUI,stats:statsUI,result:resultUI}[screen]||homeUI)()}</main>${sheetUI()}`;bind()}
function bind(){document.querySelectorAll('#app button').forEach(b=>b.onclick=()=>{
 const action=b.dataset.action,player=Number(b.dataset.player)||0;sound.unlock();if(b.dataset.key){typeKey(b.dataset.key,player);return}
 switch(action){case 'home':save();home();break;case 'book':state.book=b.dataset.id;save();render();break;case 'solo':duo=false;render();break;case 'duo':duo=true;render();break;case 'start':start(b.dataset.mode);break;case 'newRound':if(session){session.completed=true;save()}sheet=null;createRound(b.dataset.mode);break;
 case 'resume':session=state.sessions[state.book];if(session&&!session.completed)enter();break;case 'pause':stop();sheet={type:'pause'};render();break;case 'replay':play();break;case 'next':next();break;
 case 'submit':submit(player);break;case 'undo':{if(!activePlayer(player))break;const p=part(player);p.typed=p.typed.slice(0,-1);p.error='';if(session.mode==='relay'){const previous=p.used.pop();if(previous!=null)session.contributions[previous]=Math.max(0,session.contributions[previous]-1);save();render()}else inputChanged(player);break}case 'hint':hint(player);break;
 case 'skip':if(current().heard)answer(owner(),false);else toast('先听完英语，再继续');break;case 'skipPlayer':if(activePlayer(player))answer(player,false);break;
 case 'wrong':stop();screen='wrong';sheet=null;render();break;case 'reviewPlayer':reviewPlayer=player;render();break;
 case 'prevBuddy':slideBuddy(-1);break;case 'nextBuddy':slideBuddy(1);break;case 'team':stop();screen='team';sheet=null;render();break;case 'teamPlayer':teamPlayer=player;render();break;case 'partner':state.players[teamPlayer].partner=b.dataset.id;save();render();break;case 'stats':stop();screen='stats';sheet=null;render();break;
 case 'settings':sheet={type:'settings'};resetConfirm=false;render();break;case 'closeSheet':sheet=null;render();break;case 'music':case 'effects':case 'reduced':state.settings[action]=!state.settings[action];sound.music=state.settings.music;sound.effects=state.settings.effects;save();render();break;
 case 'reset':if(!resetConfirm){resetConfirm=true;render()}else{stop();state=migrate({},data);save();home()}break;
 case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>20000000)throw Error('进度文件太大');const restored=restoreProgress(await f.text(),data);if(window.confirm(`导入 ${restored.records.length} 条记录？将替换当前设备进度。`)){stop();state=restored;save();home();toast('进度已导入')}}catch(e){toast(e.message)}};input.click();break}
 case 'export':{const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));link.href=url;link.download='训练家进度.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}
 }
 });document.querySelectorAll('[data-name]').forEach(el=>el.onchange=()=>{state.players[Number(el.dataset.name)].name=el.value.trim()||'训练家';save()});
 document.querySelectorAll('[data-entry]').forEach(el=>{el.oninput=()=>{const k=Number(el.dataset.player)||0;if(!activePlayer(k))return;const p=part(k);p.typed=el.value.replace(/[^a-z '\-]/gi,'').slice(0,current().q.level===1?1:60);p.error='';inputChanged(k)};el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();submit(Number(el.dataset.player)||0)}}});
 const carousel=document.querySelector('[data-carousel]');if(carousel){let start=null;carousel.onpointerdown=e=>{if(e.target.closest('button'))return;start={x:e.clientX,y:e.clientY};carousel.setPointerCapture?.(e.pointerId)};carousel.onpointerup=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3)slideBuddy(dx<0?1:-1)};carousel.onpointercancel=()=>start=null}
}
window.addEventListener('pagehide',()=>{stop();save()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();if(screen==='play'){sheet={type:'pause'};render()}save()}});
const context=document.modelContext;if(context?.registerTool)try{context.registerTool({name:'read_learning_coverage',description:'读取当前设备重点单词覆盖，不开始游戏',inputSchema:{type:'object',properties:{book:{enum:data.books.map(b=>b.id),type:'string'}},required:['book'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({book})=>wordOverview(data,state,book)})}catch{}
save();render();
